package com.dy.artisan3d.utilimport platform.Foundation.NSURLimport platform.UIKit.UIApplicationactual fun openExternalUrl(url: String) {    val nsUrl = NSURL.URLWithString(url)    if (nsUrl != null) {        // Yangi API: openURL:options:completionHandler:        UIApplication.sharedApplication.openURL(            url = nsUrl,            options = emptyMap<Any?, Any?>(), // Hech qanday maxsus parametrlar shart emas            completionHandler = null         // Natijani kutish shart emas        )    }}